with base as (select *, ceil(balance) as balance_whole from accounts where customer_id in (12, 21, 30, 37) and status not in ('OPEN', 'FROZEN')), summary as (select status, date_format(opened_date, 'yyyy-MM') as opened_month, max(opened_date) as latest_opened_date, count(*) as account_count from base group by status, date_format(opened_date, 'yyyy-MM')) select status, opened_month, latest_opened_date, account_count from summary order by status
